pub struct FileHandle {
    file: std::fs::File,      // no #[derive(Copy, Clone)]
}

impl FileHandle {
    pub fn open(path: &str) -> std::io::Result<Self> {
        Ok(Self { file: std::fs::File::open(path)? })
    }
}

